parameters.jsCode:
const current = $('Merge').first().json;

const conversation = $('instagram_conversations')
  .all()
  .map(item => item.json);

const businessKnowledge = $('business_knowledge')
  .all()
  .map(item => item.json);

return [
  {
    json: {
      current_customer: current,
      conversation_history: conversation,
      business_knowledge: businessKnowledge
    }
  }
];

// ============================================================
// DETECT ORDER & HANDOVER INTENT
// ============================================================
// PURPOSE:
//
// This is the CENTRAL conversation + order + handover processor.
//
// EVERYTHING is intentionally kept inside this ONE Code node.
//
// It handles:
//
// 1. Input data collection
// 2. Text normalization
// 3. Helper functions
// 4. Multiple customer intent detection
// 5. Service recovery
// 6. Word-count recovery
// 7. Payment method detection
// 8. Explicit topic recovery
// 9. Flexible project-subject detection
// 10. Standalone subject detection
// 11. Business knowledge matching
// 12. Relevant business knowledge matching
// 13. Order status detection
// 14. Customer stage detection
// 15. Missing order information detection
// 16. Human handover detection
// 17. Order details construction
// 18. Handover object construction
// 19. Customer Care detection and object construction
// 20. Deterministic customer-facing response
// 21. Final structured output
//
// IMPORTANT:
//
// The CURRENT customer message is the source of truth for
// handover and Customer Care triggers.
//
// Previous customer messages are used for:
// - context
// - service recovery
// - word-count recovery
// - topic recovery
// - order reconstruction
//
// Historical messages MUST NOT independently trigger a new
// handover or Customer Care escalation.
// ============================================================


// ============================================================
// 1. GET INPUT DATA
// ============================================================

const context = $('Prepare AI Context').first().json;

const customer = context.current_customer || {};
const history = context.conversation_history || [];

const aiResponse =
  $('AI response').first().json.output?.[0]?.content?.[0]?.text || '';

const businessKnowledge =
  $('business_knowledge').all().map(item => item.json);


// ============================================================
// 2. NORMALIZE TEXT
// ============================================================

const currentMessage = String(customer.message || '').trim();

const normalize = (text) =>
  String(text || '')
    .toLowerCase()
    .replace(/[-–—]/g, '-')
    .replace(/\s+/g, ' ')
    .trim();

const message = normalize(currentMessage);

const historyText = history
  .map(item => `${item.role || ''}: ${item.message || ''}`)
  .join('\n');

const fullConversation = normalize(
  `${historyText}\nuser: ${currentMessage}\nassistant: ${aiResponse}`
);


// ============================================================
// 3. HELPER FUNCTIONS
// ============================================================

function addUnique(array, value) {
  if (value && !array.includes(value)) {
    array.push(value);
  }
}


// ------------------------------------------------------------
// Extract word count
// ------------------------------------------------------------

function extractWordCount(text) {

  const normalized = String(text || '');

  const patterns = [

    /\b(\d{1,5}(?:,\d{3})?)\s*(?:-|to)?\s*word(?:s)?\b/i,

    /\b(\d{1,5}(?:,\d{3})?)\s*-\s*word\b/i
  ];

  for (const pattern of patterns) {

    const match = normalized.match(pattern);

    if (match) {
      return Number(
        match[1].replace(/,/g, '')
      );
    }
  }

  return null;
}


// ------------------------------------------------------------
// Detect service
// ------------------------------------------------------------

function detectService(text) {

  const normalized = normalize(text);

  const servicePatterns = [

    {
      name: 'Article Writing',
      patterns: [
        /\barticle writing\b/,
        /\barticles\b/,
        /\barticle\b/
      ]
    },

    {
      name: 'Blog Writing',
      patterns: [
        /\bblog writing\b/,
        /\bblog post\b/,
        /\bblog posts\b/,
        /\bblogs\b/,
        /\bblog\b/
      ]
    },

    {
      name: 'Copywriting',
      patterns: [
        /\bcopywriting\b/,
        /\bcopywriter\b/,
        /\bcopy\b/
      ]
    },

    {
      name: 'Scriptwriting',
      patterns: [
        /\bscriptwriting\b/,
        /\bscript writing\b/,
        /\bscripts\b/,
        /\bscript\b/
      ]
    },

    {
      name: 'Ghostwriting',
      patterns: [
        /\bghostwriting\b/,
        /\bghost writing\b/,
        /\bghostwriter\b/,
        /\bghostwritten\b/
      ]
    }
  ];

  for (const service of servicePatterns) {

    for (const pattern of service.patterns) {

      if (pattern.test(normalized)) {
        return service.name;
      }
    }
  }

  return null;
}


// ============================================================
// 4. DETECT MULTIPLE INTENTS
// ============================================================

const intents = [];


// ------------------------------------------------------------
// PRICING
// ------------------------------------------------------------

if (
  /\bhow much\b/.test(message) ||
  /\bwhat(?:'s| is) the price\b/.test(message) ||
  /\bprice\b/.test(message) ||
  /\bcost\b/.test(message) ||
  /\bcharge\b/.test(message) ||
  /\brate\b/.test(message) ||
  /\bhow much will it cost\b/.test(message)
) {

  addUnique(
    intents,
    'pricing_question'
  );
}


// ------------------------------------------------------------
// DELIVERY / TURNAROUND
// ------------------------------------------------------------

if (
  /\bhow soon\b/.test(message) ||
  /\bhow long\b/.test(message) ||
  /\bdelivery\b/.test(message) ||
  /\bdeliver\b/.test(message) ||
  /\bdelivered\b/.test(message) ||
  /\bturnaround\b/.test(message) ||
  /\bwhen will\b/.test(message) ||
  /\bwhen can\b/.test(message) ||
  /\bhow fast\b/.test(message)
) {

  addUnique(
    intents,
    'delivery_question'
  );
}


// ------------------------------------------------------------
// SERVICE QUESTION
// ------------------------------------------------------------

if (
  /\bwhat services\b/.test(message) ||
  /\bservices do you offer\b/.test(message) ||
  /\bwhat do you offer\b/.test(message) ||
  /\btypes of writing\b/.test(message)
) {

  addUnique(
    intents,
    'service_question'
  );
}


// ------------------------------------------------------------
// PURCHASE INTENT
// ------------------------------------------------------------

if (
  /\bi want to order\b/.test(message) ||
  /\bi would like to order\b/.test(message) ||
  /\bwant to place an order\b/.test(message) ||
  /\bplace an order\b/.test(message) ||
  /\bi want to buy\b/.test(message) ||
  /\bi am ready to order\b/.test(message) ||
  /\bi'm ready to order\b/.test(message) ||
  /\bim ready to order\b/.test(message) ||
  /\blets order\b/.test(message) ||
  /\blet's order\b/.test(message) ||
  /\bgo ahead with the order\b/.test(message) ||
  /\bproceed with the order\b/.test(message) ||
  /\bi want to proceed\b/.test(message) ||
  /\bi'd like to order\b/.test(message) ||
  /\bi would like to proceed\b/.test(message)
) {

  addUnique(
    intents,
    'purchase_intent'
  );
}


// ------------------------------------------------------------
// PAYMENT QUESTION
// ------------------------------------------------------------

if (
  /\bhow do i pay\b/.test(message) ||
  /\bhow can i pay\b/.test(message) ||
  /\bwhere do i pay\b/.test(message) ||
  /\bpayment details\b/.test(message) ||
  /\bpayment method\b/.test(message) ||
  /\bhow to pay\b/.test(message) ||
  /\bhow much upfront\b/.test(message) ||
  /\bwhat payment do you accept\b/.test(message) ||
  /\bwhat payment methods\b/.test(message)
) {

  addUnique(
    intents,
    'payment_question'
  );
}


// ------------------------------------------------------------
// PAYMENT CONFIRMATION
// ------------------------------------------------------------

if (
  /\bi paid\b/.test(message) ||
  /\bi have paid\b/.test(message) ||
  /\bpayment sent\b/.test(message) ||
  /\bpayment made\b/.test(message) ||
  /\bsent the payment\b/.test(message) ||
  /\bpayment completed\b/.test(message) ||
  /\bi've paid\b/.test(message) ||
  /\bpayment has been sent\b/.test(message)
) {

  addUnique(
    intents,
    'payment_confirmation'
  );
}


// ------------------------------------------------------------
// GREETING
// ------------------------------------------------------------

if (
  [
    'hi',
    'hello',
    'hey',
    'good morning',
    'good afternoon',
    'good evening'
  ].includes(message)
) {

  addUnique(
    intents,
    'greeting'
  );
}


// ------------------------------------------------------------
// DEFAULT
// ------------------------------------------------------------

if (intents.length === 0) {

  addUnique(
    intents,
    'general_inquiry'
  );
}


// ============================================================
// NEW ORDER DETECTION
// ============================================================
//
// A message that explicitly asks for another/new article, blog
// post, piece, project, or order starts a NEW order.
//
// Historical service/topic/word-count values must NOT leak into
// that new order.
//
// Normal follow-ups continue to reuse history.
// ============================================================

const isNewOrderRequest =
  /\b(?:another|new)\s+(?:article|blog\s+post|piece|project|order)\b/i
    .test(currentMessage)
  ||
  /\b(?:i\s+)?(?:want|need|would like)\s+to\s+(?:order|place\s+an?\s+order\s+for)\b/i
    .test(currentMessage)
  ||
  /\b(?:can|could|would)\s+you\s+(?:write|create|produce)\b[\s\S]{0,100}\b\d{3,5}\s*(?:words?|word)\b/i
    .test(currentMessage);

// ============================================================
// 5. RECOVER SERVICE
// ============================================================

let service =
  detectService(
    currentMessage
  );


if (!service && !isNewOrderRequest) {

  for (
    let i = history.length - 1;
    i >= 0;
    i--
  ) {

    if (
      String(history[i].role || '').toLowerCase() !== 'user'
    ) {
      continue;
    }

    service =
      detectService(
        history[i].message
      );

    if (service) {
      break;
    }
  }
}


if (!service && !isNewOrderRequest) {

  service =
    detectService(
      fullConversation
    );
}


// ============================================================
// 6. RECOVER WORD COUNT
// ============================================================

let wordCount =
  extractWordCount(
    currentMessage
  );


if (
  !wordCount &&
  !isNewOrderRequest
) {

  for (
    let i = history.length - 1;
    i >= 0;
    i--
  ) {

    if (
      String(history[i].role || '').toLowerCase() !== 'user'
    ) {
      continue;
    }

    wordCount =
      extractWordCount(
        history[i].message
      );

    if (wordCount) {
      break;
    }
  }
}


// ============================================================
// 7. DETECT PAYMENT METHOD
// ============================================================

let paymentMethod = null;

if (/\busdt\b/.test(currentMessage)) {
  paymentMethod = 'USDT';
} else if (!isNewOrderRequest && /\busdt\b/.test(fullConversation)) {
  paymentMethod = 'USDT';
}

// ============================================================
// 8. FLEXIBLE TOPIC RECOVERY
// ============================================================

let topic = null;


// ------------------------------------------------------------
// 8A. CLEAN TOPIC CANDIDATE
// ------------------------------------------------------------

function cleanTopicCandidate(candidate) {

  if (!candidate) {
    return null;
  }

  let value = String(candidate)
    .trim()
    .replace(/^[\s.,;:!?\-–—_]+/, '')
    .replace(/^["“'`]+/, '')
    .replace(/["”'`]+$/, '')
    .trim();


  value = value
    .replace(
      /\s+(?:and\s+)?(?:how much|what(?:'s| is) the price|what is the cost|how soon|how long|when can|when will).*$/i,
      ''
    )
    .trim();


  value =
    value.replace(
      /[.!?]+$/,
      ''
    ).trim();


  if (!value) {
    return null;
  }


  const invalidPatterns = [

    /^of the article$/i,
    /^the article$/i,
    /^article$/i,
    /^the topic$/i,
    /^topic$/i,
    /^of the topic$/i,
    /^the subject$/i,
    /^subject$/i,
    /^it$/i,
    /^this$/i,
    /^that$/i,
    /^do you remember/i,
    /^can you remember/i,
    /^do you still remember/i,
    /^what is the topic/i,
    /^what's the topic/i,
    /^what was the topic/i,
    /^how much/i,
    /^how soon/i,
    /^how long/i,
    /^when can/i,
    /^when will/i,
    /^payment/i,
    /^delivery/i,
    /^price/i,
    /^cost/i
  ];


  if (
    invalidPatterns.some(
      pattern => pattern.test(value)
    )
  ) {

    return null;
  }


  return value;
}


// ------------------------------------------------------------
// 8B. EXPLICIT TOPIC PATTERNS
// ------------------------------------------------------------

const explicitTopicPatterns = [

  /\b(?:it|it's|its)\s+(?:going|gonna)\s+to\s+be\s+on\s*[:.\-–—]?\s*["“\']?(.+?)["”\']?(?:[.!?]|$)/i,

  /\b(?:it|it's|its)\s+(?:going|gonna)\s+to\s+be\s+about\s*["“\']?(.+?)["”\']?(?:[.!?]|$)/i,

  /\btopic\s+(?:would be|will be|is|was)\s+(?:on|about)\s+["“']?(.+?)["”']?(?:[.!?]|$)/i,

  /\btopic\s*:\s*["“']?(.+?)["”']?(?:[.!?]|$)/i,

  /\bthe\s+topic\s+(?:is|was|would be|will be)\s+(?:on|about)?\s*["“']?(.+?)["”']?(?:[.!?]|$)/i,

  /\barticle(?:'s)?\s+topic\s+(?:is|was|would be|will be)\s+(?:on|about)?\s*["“']?(.+?)["”']?(?:[.!?]|$)/i,

  /\bthe\s+article\s+(?:is|was|would be|will be)\s+about\s+["“']?(.+?)["”']?(?:[.!?]|$)/i,

  /\barticle\s+(?:is|was|would be|will be)\s+about\s+["“']?(.+?)["”']?(?:[.!?]|$)/i,

  /\bwriting\s+(?:is|was|would be|will be)\s+about\s+["“']?(.+?)["”']?(?:[.!?]|$)/i,

  /\b(?:the\s+)?subject\s+(?:is|was|would be|will be)\s+(?:on|about)?\s*["“']?(.+?)["”']?(?:[.!?]|$)/i
];


for (
  const pattern of explicitTopicPatterns
) {

  const match =
    currentMessage.match(
      pattern
    );

  if (
    match &&
    match[1]
  ) {

    const candidate =
      cleanTopicCandidate(
        match[1]
      );

    if (candidate) {

      topic = candidate;
      break;
    }
  }
}


if (
  !topic &&
  !isNewOrderRequest
) {

  for (
    let i = history.length - 1;
    i >= 0;
    i--
  ) {

    if (
      String(history[i].role || '').toLowerCase() !== 'user'
    ) {
      continue;
    }

    const text =
      String(
        history[i].message || ''
      );

    for (
      const pattern of explicitTopicPatterns
    ) {

      const match =
        text.match(
          pattern
        );

      if (
        match &&
        match[1]
      ) {

        const candidate =
          cleanTopicCandidate(
            match[1]
          );

        if (candidate) {

          topic = candidate;
          break;
        }
      }
    }

    if (topic) {
      break;
    }
  }
}


// ============================================================
// 9. FLEXIBLE PROJECT-SUBJECT DETECTION
// ============================================================

if (!topic) {

  const naturalTopicPatterns = [

    // --------------------------------------------------------
    // NEW ORDER + CURRENT TOPIC
    // --------------------------------------------------------
    // Examples:
    //
    // "I want to order another article on how to become a professor"
    // "I want to order a new article about AI in education"
    // "I would like to order another article on leadership"
    // "I want to place an order for a 3000 words article on 30 ways to stay focused in life"
    // --------------------------------------------------------

    /\b(?:i\s+)?(?:want|need|would like)\s+to\s+(?:order|place\s+an?\s+order\s+for)\s+(?:an?\s+)?(?:another|new)?\s*(?:article|blog post|piece)\s+(?:on|about|covering|focused on)\s+(.+?)(?:[.!?]|$)/i,

    // --------------------------------------------------------
    // NORMAL ARTICLE / BLOG / PIECE REQUEST
    // --------------------------------------------------------

    /\b(?:i\s+)?(?:need|want|would like|am looking for)\s+(?:an?\s+)?(?:article|blog post|piece)\s+(?:on|about|covering|focused on)\s+(.+?)(?:[.!?]|$)/i,

    /\b(?:write|create|prepare|produce)\s+(?:an?\s+)?(?:article|blog post|piece)\s+(?:on|about|covering|focused on)\s+(.+?)(?:[.!?]|$)/i,

    /\b(?:write|writing)\s+(?:something\s+)?(?:about|on)\s+(.+?)(?:[.!?]|$)/i,

    /\b(?:an?\s+)?article\s+(?:on|about)\s+(.+?)(?:[.!?]|$)/i,

    /\b(?:a\s+)?piece\s+(?:on|about)\s+(.+?)(?:[.!?]|$)/i,

    /\b(?:article|piece|blog(?:\s+post)?)\s+(?:should|needs to|has to)\s+(?:cover|discuss|focus on)\s+(.+?)(?:[.!?]|$)/i
  ];


  // ==========================================================
  // 9A. CURRENT MESSAGE ALWAYS WINS
  // ==========================================================

  for (
    const pattern of naturalTopicPatterns
  ) {

    const match =
      currentMessage.match(
        pattern
      );

    if (
      match &&
      match[1]
    ) {

      const candidate =
        cleanTopicCandidate(
          match[1]
        );

      if (candidate) {

        topic = candidate;

        break;
      }
    }
  }


  // ==========================================================
  // 9B. ONLY IF CURRENT MESSAGE HAS NO TOPIC,
  //     RECOVER FROM HISTORY
  // ==========================================================

  if (
    !topic &&
    !isNewOrderRequest
  ) {

    for (
      let i = history.length - 1;
      i >= 0;
      i--
    ) {

      if (
        String(history[i].role || '').toLowerCase() !== 'user'
      ) {
        continue;
      }


      const text =
        String(
          history[i].message || ''
        );


      for (
        const pattern of naturalTopicPatterns
      ) {

        const match =
          text.match(
            pattern
          );


        if (
          match &&
          match[1]
        ) {

          const candidate =
            cleanTopicCandidate(
              match[1]
            );


          if (candidate) {

            topic = candidate;

            break;
          }
        }
      }


      if (topic) {
        break;
      }
    }
  }
}


// ============================================================
// 10. STANDALONE SUBJECT DETECTION
// ============================================================

if (
  !topic &&
  !isNewOrderRequest
) {

  const customerMessages = history
    .filter(item =>
      String(item.role || '').toLowerCase() === 'user'
    )
    .map(item =>
      String(item.message || '').trim()
    );

  customerMessages.push(
    currentMessage
  );


  const writingContext =
    customerMessages.some(text => {

      const normalizedText =
        normalize(text);

      return (
        /\b(?:article|blog|copywriting|script|ghostwriting|writing service|writing services)\b/i
          .test(normalizedText)
      );
    });


  if (writingContext) {

    for (
      let i = customerMessages.length - 1;
      i >= 0;
      i--
    ) {

      const text =
        customerMessages[i].trim();

      const normalizedText =
        normalize(text);


      if (
        /[?]$/.test(text) ||
        /^(?:do|does|did|is|are|am|can|could|would|will|what|when|where|how|why)\b/i.test(text)
      ) {
        continue;
      }


      if (
        /^(?:how much|what(?:'s| is) the price|what is the cost|how soon|how long|when can|when will|how do i pay|where do i pay)\b/i
          .test(normalizedText)
      ) {
        continue;
      }


      let candidate =
        text
          .replace(
            /^(?:the\s+)?(?:article|blog post|piece|subject|topic)\s*(?:is|would be|will be|was)?\s*/i,
            ''
          )
          .trim();


      candidate =
        cleanTopicCandidate(
          candidate
        );


      if (
        candidate &&
        candidate.length <= 160 &&
        candidate.split(/\s+/).length <= 25
      ) {

        const genericOrderPatterns = [

          /^i want to order/i,
          /^i would like to order/i,
          /^i want to buy/i,
          /^place an order/i,
          /^i am ready to order/i,
          /^i'm ready to order/i,
          /^how much/i,
          /^how soon/i,
          /^how long/i,
          /^what services/i
        ];


        if (
          !genericOrderPatterns.some(
            pattern =>
              pattern.test(candidate)
          )
        ) {

          topic = candidate;
          break;
        }
      }
    }
  }
}


// ============================================================
// 11. BUSINESS KNOWLEDGE MATCHING
// ============================================================

let matchedBusinessKnowledge = [];

let price = null;
let currency = null;
let deliveryTime = null;


// ------------------------------------------------------------
// Exact service + word count
// ------------------------------------------------------------

if (
  service &&
  wordCount
) {

  const exactMatch =
    businessKnowledge.find(item =>
      item.active !== false &&
      item.category === 'faq' &&
      item.service === service &&
      Number(item.word_count) === Number(wordCount)
    );


  if (exactMatch) {

    price =
      exactMatch.price ??
      null;

    currency =
      exactMatch.currency ??
      null;

    deliveryTime =
      exactMatch.delivery_time ??
      null;

    matchedBusinessKnowledge.push(
      exactMatch
    );
  }
}


// ------------------------------------------------------------
// Turnaround
// ------------------------------------------------------------

if (wordCount) {

  const turnaroundMatch =
    businessKnowledge.find(item =>
      item.active !== false &&
      item.category === 'turnaround' &&
      Number(item.word_count) === Number(wordCount)
    );


  if (turnaroundMatch) {

    if (!deliveryTime) {

      deliveryTime =
        turnaroundMatch.delivery_time ??
        null;
    }


    if (
      !matchedBusinessKnowledge.includes(
        turnaroundMatch
      )
    ) {

      matchedBusinessKnowledge.push(
        turnaroundMatch
      );
    }
  }
}


// ------------------------------------------------------------
// Price calculation fallback
// ------------------------------------------------------------

if (
  price === null &&
  service &&
  wordCount
) {

  const serviceRate =
    businessKnowledge.find(item =>
      item.active !== false &&
      item.category === 'service' &&
      item.service === service
    );


  if (
    serviceRate &&
    serviceRate.price != null
  ) {

    price =
      Number(serviceRate.price) *
      Number(wordCount);

    currency =
      serviceRate.currency ||
      currency ||
      'USD';


    if (
      !matchedBusinessKnowledge.includes(
        serviceRate
      )
    ) {

      matchedBusinessKnowledge.push(
        serviceRate
      );
    }
  }
}


// ============================================================
// 12. MATCH RELEVANT BUSINESS KNOWLEDGE
// ============================================================

const relevantKnowledge =
  businessKnowledge.filter(item => {

    if (
      item.active === false
    ) {
      return false;
    }


    if (
      service &&
      item.service === service
    ) {

      if (
        item.word_count != null &&
        wordCount &&
        Number(item.word_count) !== Number(wordCount)
      ) {
        return false;
      }

      return true;
    }


    if (
      wordCount &&
      item.category === 'turnaround' &&
      Number(item.word_count) === Number(wordCount)
    ) {

      return true;
    }


    if (
      paymentMethod &&
      item.category === 'policy' &&
      item.service === 'Payment'
    ) {

      return true;
    }


    if (
      intents.includes('pricing_question') &&
      item.category === 'faq' &&
      item.question &&
      /price|cost|pricing/i.test(
        item.question
      )
    ) {

      return true;
    }


    if (
      intents.includes('delivery_question') &&
