    handoverRequired,

  reason:
    handoverReason
};


// ============================================================
// 19. BUILD CUSTOMER CARE
// ============================================================

const customer_care = {

  required:
    customerCareRequired,

  reason:
    customerCareReason
};


// ============================================================
// 20. BUILD CUSTOMER-FACING INSTAGRAM RESPONSE
// ============================================================

let final_ai_response = aiResponse;

if (
  intents.includes('purchase_intent') &&
  service &&
  wordCount &&
  topic &&
  price !== null
) {

  const deliveryDisplay = deliveryTime
    ? String(deliveryTime).replace(/\s+days?\s*$/i, ' days')
    : 'To be confirmed';

  const upfrontAmount = Number(price) * 0.5;

  final_ai_response =
    `Perfect — I’ve got your order.\n\n` +
    `📝 Topic\n` +
    `“${String(topic).trim()}”\n\n` +
    `📋 Order Details\n` +
    `• Service: ${service}\n` +
    `• Word count: ${Number(wordCount).toLocaleString()}\n` +
    `• Total: $${Number(price).toLocaleString()} ${currency || 'USD'}\n` +
    `• Upfront: $${upfrontAmount.toLocaleString()} USDT\n` +
    `• Delivery: ${deliveryDisplay}\n` +
    `• Revisions: 3\n\n` +
    `Would you like me to send the USDT payment details here so we can begin?`;
}


// ============================================================
// 20A. DETERMINISTIC PAYMENT HANDOVER RESPONSE
// ============================================================

if (
  handoverRequired &&
  handoverReason === 'customer_ready_to_make_payment'
) {

  final_ai_response =
    `Perfect — I’ll have our team take over and send you the USDT payment details here.`;
}


// ------------------------------------------------------------
// Payment already sent / payment requires verification
// ------------------------------------------------------------

if (
  handoverRequired &&
  handoverReason === 'payment_requires_verification'
) {

  final_ai_response =
    `Thanks — I’ll have our team verify the payment and get back to you shortly.`;
}


// ============================================================
// 21. RETURN FINAL STATE
// ============================================================

return {
  json: {

    current_customer:
      customer,

    conversation_history:
      history,

    business_knowledge:
      businessKnowledge,

    ai_response:
      aiResponse,

    final_ai_response:
      final_ai_response,

    intents:
      intents,

    customer_stage:
      customer_stage,

    order_status:
      order_status,

    order_details:
      order_details,

    order_id:
      order_id,

    missing_information:
      missingInformation,

    handover:
      handover,

    customer_care:
      customer_care,

    matched_business_knowledge:
      matchedBusinessKnowledge

  }
};

